
/* Enable answer engine. Retrieval over this site's own pages, built at deploy time.
   No model, no backend: it finds the passage that actually answers and cites the page. */
(function(){
  var INDEX = [{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"We work every layer of the stack, from the data underneath to the agents on top.","x":"An agent is only as good as the data and the workflows beneath it. Enable builds across Data 360, Customer 360, Agentforce and AIforce, and we are honest about which layer your problem actually sits in."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Four layers. Most partners are strong at one of them.","x":"Salesforce now sells a stack rather than a product, and the usual failure mode is a partner who is excellent at the layer they came from and vague about the rest. Enable is hands-on at all four. That matters most when the fix for an agent that keeps getting things wrong turns out to be a data model two layers down."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"AIforce","x":"Claudeforce, Slackforce, Coworker and the headless toolkit: where your people actually meet the platform. We design the surfaces the work happens in, rather than assuming everyone will log into Salesforce to do their job."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Agentforce","x":"Piper, Casey, Fin, Carter and the agents you build yourself. We design, ground, guardrail and evaluate them against real cases. An agent nobody can supervise does not go to production, whatever the demo looked like."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Customer 360","x":"Sales, Service, Field, Marketing, Commerce, Revenue, Industries and Tableau. The layer that still does most of the actual work, and the one that has to be right before an agent has anything reliable to act on."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Data 360","x":"Integration, federation and harmonisation through MuleSoft, Informatica and Agent Fabric. Identity resolution, calculated insights and the semantics that make grounding work. Quietly, this is where most AI programmes come apart."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"The people you meet do the work","x":"No bench of juniors, and no handover to someone you have never spoken to. Senior practitioners from the first call through to the handover."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"We start with the business","x":"Before we open Salesforce we want to know what you are trying to do and what has already been tried. Sometimes the answer is a build. Sometimes it is a small change. Sometimes it is that Salesforce is not the tool."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"In the new capabilities since launch","x":"Data 360, Agentforce and Agentforce Marketing have been part of our practice from the day each shipped, not added to the website when the demand turned up."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Scoped honestly, priced up front","x":"Fixed scope, fixed price and fixed date wherever the work allows it. No padded hours, no surprise invoices, and nothing on the bill you cannot point to."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"We tell you what you need to hear","x":"We would rather have a useful conversation than win a project that should not have happened. That goes for scope, for timing, and for whether the platform fits at all."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"No lock-in","x":"No lock-in contracts, non-competes or minimum terms. Even Waypoint, our continuous improvement programme, runs month to month. If we are delivering, the contract will not be the reason you stay."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Where Salesforce stops, these three carry on.","x":"We implement products rather than resell them, and we only take on ones we would put into our own org. Each is native to Salesforce, so nothing here adds a second system to keep in sync. Website, eCommerce and point of sale, inside Salesforce. One catalogue and one customer record across web, counter and CRM, with no connector in between. Agreements that never leave Salesforce. Documents generated from your records, signed without an account, and filed back automatically. Built in Christchurch. The reason your team"},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Start with a build","x":"Fixed scope, fixed price, fixed date. Three to four weeks each, and each one becomes the first entry on your Waypoint backlog rather than a project that simply ends. Larger programmes run the same way, phase by phase."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Keep improving with Waypoint","x":"A standing programme of review, prioritisation and build. Every quarter we look at what the platform is actually doing, you decide what is worth changing, and we change it. Month to month, no minimum term."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Training and enablement","x":"Adoption is a people problem, not a licensing one. The measure of a good course is that you stop needing us for routine work."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Let's talk about your business first.","x":"Tell us what you are trying to do. We will tell you which layer of the stack it lives in, what it would take, and whether it is worth doing at all. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Continuous improvement for a platform that does not stay finished.","x":"Waypoint is a standing programme of review, prioritisation and build. Every quarter we look at what your platform is actually doing, agree what is worth changing, and change it. Month to month, no minimum term. Four steps, repeated. Nothing enters the backlog that you have not chosen at step two."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Most Salesforce orgs peak on the day they go live.","x":"The project ends, the consultants leave, and the platform starts drifting. Fields get added without a reason. Reports multiply. Adoption slips quietly. Two years later somebody proposes a rebuild, and the business pays a second time for capability it already owned."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Nobody owns the roadmap","x":"After go-live the backlog becomes whatever was escalated most recently. Improvement stops being planned and starts being reactive."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Change without a record","x":"Fields, flows and permissions accumulate. Nobody can say why any of it is there, which makes the next change slower than the last one."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Adoption decays quietly","x":"Usage falls well before anyone reports a problem. By the time it shows up in a number, the habit has already gone."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Paid-for capability sits unused","x":"Three Salesforce releases a year ship features you are already licensed for. Without someone watching, they stay switched off."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"One loop, run every quarter","x":"The same four steps each quarter, so the platform improves on a cadence rather than whenever something breaks loudly enough."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Review","x":"We look at what the platform is actually doing: adoption by team, data quality, automation failing quietly, technical debt, and the capability in the last three releases that you are paying for and not using."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Prioritise","x":"Findings come to you with an effort estimate against each one, and you decide what is worth doing. Nothing enters the backlog that you have not chosen, and anything you decline comes off the list rather than reappearing."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Build","x":"The agreed work is built, tested and released by the same senior practitioners who reviewed it. Every change is documented as it lands, so the record is never reconstructed from memory six months later."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Measure","x":"The next review opens with what changed and what it moved. Where something did not move, we say so plainly and it comes off the list rather than being restated as a win."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"A named senior practitioner","x":"The same person every month. They learn your org properly, and you stop re-explaining it at the start of every request."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Agreed build capacity","x":"A set allocation of build days each month, spent on the backlog you prioritised. Unused days roll forward one month so a quiet period is not simply lost."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Quarterly platform review","x":"Adoption, data quality, automation health, security and technical debt, written up with findings ranked by what they are costing you rather than by how interesting they are."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Release readiness","x":"Three Salesforce releases a year, checked against your org before they land rather than after something stops working on a Monday morning."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Documentation that stays current","x":"Configuration and change documentation updated as work lands, plus a decision register with the reasoning kept alongside each decision."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Advisory access","x":"The conversation about whether something is worth doing, before it becomes a request. Often the most valuable part, and the hardest to buy by the hour."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Build something first, then keep improving it","x":"Most organisations join Waypoint by building a capability first. Each of these is fixed scope, fixed price and fixed date, and becomes the first entry on your Waypoint backlog rather than a project that simply ends."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Agentforce Pilot","x":"One production-ready agent handling one real, repetitive workflow, with guardrails."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Marketing Cloud Next Kickstart","x":"Your first Flow-driven campaign live, reaching the right person at the right time."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"How it is priced","x":"A monthly fee set by the build allocation you want, agreed before you start. Unused days roll forward one month. Change the allocation, pause, or stop, with a month's notice."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"What it does not cover","x":"Work larger than the monthly allocation is quoted as a separate fixed-price piece rather than absorbed quietly. Salesforce licence costs, third-party product support and end-user training beyond ad hoc guidance sit outside it."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Why there is no term","x":"Enable does not use lock-in contracts, non-competes or minimum terms, and Waypoint is no exception. A programme that has to be contractually enforced is not delivering. If it is worth having, the invoice will not be the reason you stay."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Find out what your platform is actually doing.","x":"The first platform review stands on its own. You get the findings and the estimates whether or not you carry on into Waypoint, and plenty of organisations take the report and fix things themselves. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Salesforce, built around what your business actually does.","x":"Sales Cloud, Service Cloud, Data 360, Agentforce and Agentforce Marketing, delivered by senior practitioners who ask what you are trying to do before opening the platform. What are you trying to do? Who is the work actually for? What has already been tried? What happens if nothing changes? A lot of the time the answer is not a new feature. It is a clearer view of the problem."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Five practices, one team, no handover between them.","x":"Most projects touch more than one of these, and the seams are where things usually go wrong. The same people work across all five, so the conversation about how marketing data reaches a service agent happens in the room rather than between two firms."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Sales Cloud","x":"Pipeline that matches how your team actually sells, stages that mean something, and a forecast your CFO will not laugh at. Territory, quoting and partner management where the model needs them."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Service Cloud","x":"Case management, Omni-Channel routing, knowledge and entitlements. Built so the person answering knows what they are looking at, and so the SLA reflects an actual commitment."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Data 360","x":"The single customer view you keep being told you have. Identity resolution, calculated insights, activations into everything else, and honest modelling of what the credits will cost before you commit."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Agentforce","x":"Agents doing real work: deflecting cases, supporting sellers, running the internal jobs nobody got to. Designed, grounded, guardrailed and evaluated against actual cases before anything reaches a customer."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Agentforce Marketing","x":"Marketing Cloud Next on the core platform. Audiences from Data 360, journeys built in Flow, and campaigns that do not read like a 2014 email blast. Migration from SFMC or Pardot where that is the starting point."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"And the parts around them","x":"Integration, migration, sharing and security models, Experience Cloud, Tableau, and the governance that keeps an org from turning into a museum. Rarely the headline, usually the reason a project lands."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Understand the problem","x":"Before we open Salesforce we want to know what you are trying to do, who the work is for, and what has already been tried. Sometimes the answer is a major build. Sometimes it is a small change. Sometimes it is that Salesforce is not the right tool at all, and we will say so."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Scope it honestly","x":"Fixed scope, fixed price and fixed date wherever the work allows it, agreed before anything starts. No padded hours, no surprise invoices, and nothing on the bill you cannot point to. Where genuine uncertainty exists it goes in the assumptions, not scattered through the scope."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Build it ourselves","x":"The people you meet are the people who do the work. No bench of juniors, and no handing your project to someone you have never spoken to. Senior practitioners from the first call through to the handover."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Hand it over properly","x":"Configuration documentation, change and decision registers, training material and user guides, written on the assumption you may never need to call us again. If you want to keep improving it from there, that is what Waypoint is for."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Let's talk about your business first.","x":"We would rather have a useful conversation than win a project that should not have happened. That goes for scope, for timing, and for whether the platform fits at all. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. Auckland and Wellington. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"We started Enable because we kept seeing the same problem.","x":"Good organisations with a Salesforce platform that was not doing what it should. Money had been spent and features switched on, but the work that mattered still was not getting done."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"The issue was rarely the technology.","x":"It was that nobody had started with the business. So that is where we start. Business first, Salesforce second. We want to understand what you are trying to do before we talk about how the platform fits. Sometimes the answer is a major build. Sometimes it is a small change. Sometimes it is telling you that Salesforce is not the right tool at all, which is a conversation that costs us a project and saves you one. We work across the full platform: Sales Cloud, Service Cloud, Data 360, Agentforce and Agentforce Market"},{"p":"about","t":"About Enable: business first, Salesforce second","h":"The people you meet do the work","x":"No bench of juniors. No handing your project to someone you have never spoken to. Senior practitioners from the first call through to the handover, which is also why we take on fewer projects than we could."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"We scope honestly","x":"Fixed price agreed up front, and we do the work ourselves. No padded hours, no surprise invoices, nothing on the bill you cannot point to."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"We tell you what you need to hear","x":"We would rather have a useful conversation than win a project that should not have happened. That goes for scope, for timing, and for platform fit."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"No lock-in","x":"No lock-in contracts, non-competes or minimum terms. Even Waypoint, our continuous improvement programme, runs month to month. If we are delivering, the contract will not be why you stay."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"First in the region on the new things","x":"Enable was the first partner in APAC to deliver Marketing Cloud Next, with seven implementations since. Specific and checkable beats \"extensive experience\"."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"You keep everything","x":"Configuration and change documentation, decision registers with the reasoning, training material. Written on the assumption you may never need to call us again."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"Blair Rooney","x":"Managing Director If you engage Enable, this is who you are working with. Not a sales lead who hands you over after the kick-off, and not a delivery manager reading someone else\u2019s notes."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"If that is the kind of partner you are looking for, we should talk.","x":"Tell us what you are trying to do. We will tell you which layer of the stack it lives in, what it would take, and whether it is worth doing at all. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Let\u2019s talk about your business first.","x":"Tell us what you are trying to do. We will tell you which layer of the stack it lives in, what it would take, and whether it is worth doing at all."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Send us a note","x":"We reply to everything, usually the same working day. No mailing list, no drip sequence."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"A reply, usually same day","x":"From Blair, not an account manager and not an automated acknowledgement. If we are not the right people for what you are describing, that is what the reply will say."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"A conversation, not a pitch","x":"Half an hour to understand what you are trying to do, who the work is for, and what has already been tried. We will ask more questions than we answer, which is the point."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"A written recommendation","x":"Where it is warranted: what we think the work is, roughly what it costs, and what we would do first. Including the recommendation not to proceed where that is the honest answer."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Talk to Blair directly","x":"Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. The people you meet are the people who do the work, which starts with this call."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Where we work","x":"Auckland and Wellington, working with organisations across New Zealand and Australia. On site when it helps, remote when it does not."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"What it costs to ask","x":"Nothing. A first conversation is not a sales process, and we would rather tell you early that something is not worth doing than find out together in month four."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Not sure it is even a Salesforce problem?","x":"Ask anyway. A useful conversation beats a project that should not have happened, and we are reasonably good at telling the difference early. Enable Digital. Auckland and Wellington. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Your store and your CRM should be one system. With StoreConnect, they are.","x":"Enable builds websites, online stores and point of sale natively on Salesforce. One catalogue, one customer record, one place your team already works. The arrows are not integrations. All three write to the same Salesforce record directly."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Most commerce projects finish with two systems and an expensive sync between them.","x":"The storefront goes on Shopify or WooCommerce. The customer record stays in Salesforce. Between them sits a connector, a nightly job and someone whose real job has quietly become reconciling orders. It holds together until it doesn't, and the first sign is usually a report that no longer matches the one beside it."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Two customer records","x":"Someone who buys online and again at the counter becomes two contacts, and neither history is complete."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Reports that disagree","x":"Finance, marketing and service each quote a different number, because each is reading a different system."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Integration as a running cost","x":"Middleware licences, connector upgrades and the one developer who understands them become a permanent line item."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Automation that stops at the border","x":"Salesforce cannot act on an abandoned cart, a stock hold or a warranty claim it never sees."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"StoreConnect is an AppExchange package. The store runs inside Salesforce.","x":"There is no API layer and no external database. Products, pricing, stock, orders, customers, pages and content are Salesforce records. Your admins already know how to change them, your reports already know where to find them, and your Flows can act on them the moment they are created."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Website and CMS","x":"Pages, blogs, navigation and media managed as Salesforce records, with full control of the theme, CSS and custom JavaScript. Media is served through a CDN."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"eCommerce","x":"Physical goods, digital products, events, bookings, subscriptions, memberships and donations. Promotions, loyalty points, gift cards and account credit, with no order limits."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Point of sale","x":"Card terminals, cash drawers, receipt and label printers, scanners and roving tablets, with no hardware lock-in and an offline mode that resyncs when the connection returns."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Multi-store, multi-currency","x":"Several storefronts, brands or regions on one back end, with their own pricebooks, region-based tax and shared stock. Sell in NZD and anything else at the same time."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Agentforce agents","x":"Commerce agents grounded in your own catalogue, policies and order history. They read the same records your staff do, so there is no knowledge base to retrain when a price changes."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Security and compliance","x":"SOC 2, ISO 27001, PCI DSS 4.0.1 and GDPR, on Salesforce infrastructure. One system to certify instead of three, and one less place cardholder data can sit."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"You already run Salesforce","x":"You have Sales Cloud or Service Cloud and now need to sell online, or a storefront that never properly connected to either. StoreConnect puts commerce on the records you already trust, so pipeline, cases and orders finally sit together."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"You are comparing platforms","x":"Shopify and BigCommerce will get you selling quickly. The cost turns up later, in integration work and a second set of customer data. If a single view of the customer matters more than a theme marketplace, that comparison is worth running properly. We will run it with you."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"You are a not-for-profit","x":"One-off and recurring donations, memberships, event tickets, merchandise and in-person sales, all against one supporter record. The account portal needs no Experience Cloud licences, which changes the sums considerably for a charity."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"What an Enable StoreConnect build looks like","x":"Each stage stands on its own. You can stop after the first one, and some organisations should."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Fit assessment","x":"Two weeks. We look at your catalogue, your selling model, the state of your Salesforce org and the systems StoreConnect would replace. You get a written recommendation with a real number attached, including the recommendation not to proceed where that is the right answer."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Foundation","x":"Data model, product and pricebook structure, stock, region-based tax, shipping and payment providers, and the Salesforce configuration commerce depends on. Delivered as a working store you can transact against, not a document describing one."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Storefront and point of sale","x":"Theme, content, checkout, customer portal, and the register and hardware configuration for each site. Built to your brand rather than a template with your logo dropped into it. Where Agentforce is in scope, the commerce agent is grounded and evaluated here."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Handover and support","x":"Training for the people who will run the store every day, full configuration and change documentation, and a support arrangement sized to what you actually need. The handover is written on the assumption you may never need to call us again."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"No lock-in","x":"Enable does not use lock-in contracts, non-competes or retainers. We believe in delivering a successful project: on budget, on time, and to the satisfaction of the customer. If we have done that, you will keep working with us because you want to."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"StoreConnect licensing","x":"StoreConnect charges a shared success fee on each transaction rather than a per-user licence, across three plan tiers that differ by storefront count, register count, hosting and support SLA. Volume drives the cost, not headcount, and the fee is capped per transaction. We size it with you before you commit to anything."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Enable implementation","x":"Fixed price, agreed before we start. We scope the work honestly and do it ourselves: no padded hours, no surprise invoices, and nothing on the bill you cannot point to. The fit assessment is priced separately and deliberately small, so you can stop after it without having bought a build."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Organisations already running on StoreConnect","x":"These are StoreConnect platform customers, delivered across its global partner network."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Sharp Australia","x":"Several legacy websites and servers replaced by one installation covering B2B, B2C, support referrals and admin."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Playbill","x":"Multiple merchandise stores across brands and currencies, with click and collect."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Surf Life Saving Services","x":"Course bookings, equipment sales and fundraising on one platform, with LMS integration."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Grace Cosmetics","x":"A consumer storefront with the reporting and management back end built out in Salesforce."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Do we need Experience Cloud licences?","x":"No. The customer account portal does not require them, and it works with SSO if you already run a portal of your own."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"What happens to our ERP or accounting system?","x":"It stays where it is. StoreConnect sits in Salesforce alongside the integrations you already have, and the StoreConnect ecosystem covers Xero, GoldFinch, NAO and others natively."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Can we keep our current website design?","x":"Yes. The theme is fully adjustable, with custom CSS and JavaScript, so we rebuild the front end to your existing brand rather than asking you to accept a template."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"How long does an implementation take?","x":"A single storefront on a healthy Salesforce org is a matter of weeks. Multi-store, multi-currency or point of sale rollouts take longer. The fit assessment is where you get a real date."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Does it work properly in New Zealand?","x":"Yes. Multi-currency and region-based tax are standard, several payment and shipping providers are supported, and local region hosting is available on the higher plans."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Tell us what you sell, and how.","x":"A short conversation is usually enough to tell whether StoreConnect is the right answer for you. If it is not, we will say so, and point you at what is. Auckland and Wellington. Salesforce partner across Sales Cloud, Service Cloud, Data 360, Agentforce and Agentforce Marketing. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Agreements that never leave Salesforce.","x":"Enable implements Lumin Sign for Salesforce: agreements generated from your records, sent, signed and filed back against the right object, without anyone leaving the CRM or rekeying a name. The top row never leaves the platform. The bottom row is the five steps it removes."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"The agreement is the one part of the deal that leaves the CRM.","x":"Everything up to the signature lives on the record. Then someone exports to Word, retypes the client details, uploads to a signing tool, chases it by email, downloads the signed copy and drags it back into Salesforce. Each of those steps is a place for the version to drift or the file to go missing."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Details retyped, and sometimes wrong","x":"Names, entity details, amounts and dates already sit on the record. Retyping them into a template is both slow and the most common source of a document that has to be reissued."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Nobody can see where it is","x":"Once a document is out for signature it disappears from the pipeline view. The status lives in someone's inbox, and the forecast quietly stops reflecting reality."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"The signed copy ends up somewhere else","x":"A shared drive, an inbox, occasionally a laptop. When the audit or the dispute arrives, finding the executed version becomes its own small project."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Templates driven by your records","x":"Connect your Salesforce data to your contract templates once, and customer details flow into every document from then on. The document is generated from the record, so the record is always the source of truth."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Recipients sign without an account","x":"No sign-up, no password, no authentication maze between your customer and a completed agreement. The single largest cause of signing drop-off, removed."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Status on the record, automation on top","x":"Sent, viewed, signed and declined are Salesforce data, which means Flow can act on them. Stage changes, task creation, onboarding kick-off and reminders all become things the platform does rather than things a person remembers."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Encrypted, SOC 2, and filed correctly","x":"All transmission encrypted, SOC 2 compliance, full audit trail, and the executed copy filed against the right object automatically. When the audit arrives, the answer is a related list rather than a search."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"The product is the easy part. The process around it is the work.","x":"Installing a managed package takes an afternoon. Making signing a reliable step in how your business actually sells takes rather longer, and that is the part we do."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Document and template design","x":"Your agreements rebuilt as templates that pull from the record, including the conditional clauses that change by product, region or entity type."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Quote-to-signature process","x":"Where signing sits in the sales process, who approves what before it goes out, and what the platform does automatically once it comes back signed."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Automation and notifications","x":"Flows that move the stage, raise onboarding tasks, chase the reminder and tell the right person, built on the signature status rather than on someone checking."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Records, retention and handover","x":"Where executed documents are filed, who can see them, how long they are kept, and the documentation your team needs to run it without us."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Tell us what you send out for signature.","x":"Quotes, contracts, consent forms, engagement letters or enrolments. If it starts life on a Salesforce record, it can finish there too. A New Zealand consultancy implementing a New Zealand product. Auckland and Wellington. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Your team keeps exporting to a spreadsheet. This is why.","x":"Salesforce makes editing one record easy and editing forty records painful. Enable implements GridMate, a suite of 32 Lightning components that closes the gap: real inline editing, grids, calendars, kanban and maps, on the records you already have. The screen your team currently exports. This is the one worth rebuilding first."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Thirty-two components, aimed squarely at the reasons people leave Salesforce.","x":"Every export to Excel is a small vote against the platform, and a data quality problem waiting to happen. GridMate removes the reason for the export rather than writing a policy against it."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Grids and inline editing","x":"User Grid, Pivot Grid, List View Grid and Related List Grid. Update many fields and record types at once, with four levels of filtering, grouping and sorting."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Calendars and Gantt","x":"Multi, single and compact calendars plus a Gantt chart, for teams scheduling work against records rather than in a separate tool."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Kanban and maps","x":"Kanban boards on list views and field sets, map lists and record maps, for work that is easier to see as a board or a territory than as a table."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Layout and navigation","x":"Record cards, object timelines, dynamic tabs and accordions, and a file explorer. Related records visible and editable without switching tab."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"RevenueMate, from the same team","x":"Salesforce CPQ has entered end-of-sale, and mid-market organisations now need a path that is not a Revenue Cloud programme. RevenueMate is a Salesforce-native CPQ built by the GridMate team, aimed at exactly that gap: enterprise capability without the implementation that usually comes with it. Where this stands."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Sub-second pricing","x":"Complex quotes priced without the wait that makes sellers quote in a spreadsheet instead."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Nested bundle configurator","x":"Product configuration for real catalogues, with a customisable pricing rules engine behind it."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Margin visible while quoting","x":"Real-time margin on the quote, so discount conversations happen before approval rather than after."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Approvals, audit and signing","x":"Multi-level approval workflows, full audit trails, and vendor-agnostic e-signature. Lumin slots in here."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Components are cheap. Deciding where they belong is the work.","x":"Dropping 32 components onto every page makes an org worse, not better. We work out which views actually cause the spreadsheet exports, and fix those."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Find the actual friction","x":"We watch how your team really works and find the three or four screens where people give up and export. Those are the ones worth rebuilding."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Configure to the role","x":"A grid for a service team and a grid for a finance team are different grids. Filters, columns, permissions and record-type behaviour set per role."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Protect the data model","x":"Bulk editing is powerful in both directions. Validation, field-level security and sharing checked before anyone can change forty records at once."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Measure whether it worked","x":"Adoption before and after, and report exports tracked. If the spreadsheet habit does not fall, the change did not work and we say so."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Which screen does your team keep exporting?","x":"Tell us that, and we can usually tell you within a call whether GridMate fixes it or whether the problem is the data model underneath. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Fundraising, programmes and the people behind both, on one platform.","x":"Agentforce Nonprofit, still widely called Nonprofit Cloud, puts giving, programme delivery, case management and outcomes on core Salesforce objects. Enable builds it around how your organisation actually works."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"What Nonprofit Cloud actually covers","x":"It is broader than fundraising, and that breadth is the point. Most nonprofits run a CRM for donors and something else entirely for the work the donations pay for. Nonprofit Cloud is the first credible Salesforce answer to having both in one place."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Fundraising","x":"Gift transactions, gift commitments for recurring giving, designations and soft credits, with donor rollups that do not need a nightly job to be trusted."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Programme management","x":"Programmes, cohorts, enrolments and service delivery, so the work the organisation actually does is a record rather than a spreadsheet beside the CRM."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Case management","x":"Client intake, assessment, referral and review for social services, with the confidentiality and sharing model that kind of data demands."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Outcome measurement","x":"Indicators, baselines and results tracked against programmes, so the impact report is generated from the data rather than reconstructed each year."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Grantmaking","x":"For funders: applications, review, award, disbursement and reporting, on the same platform as the relationships behind them."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Volunteers and supporters","x":"Volunteer roles, shifts and hours alongside the household and constituent model, so a person who gives time and money is one record, not two."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Supporters, not customers","x":"A person can be a donor, a volunteer, a service user and a board member at once. A data model built for B2B sales handles that badly, and the damage shows up in the stewardship rather than in a report."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Budget scrutiny is public","x":"Spending on systems is visible to funders and sometimes to media. Complimentary discovery, capped fees and paying only for days used are not niceties here, they are how the decision gets defended internally."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"The mission argument is real","x":"Better supporter data means more money reaching the cause and less staff time on reconciliation. We will make that connection once, with numbers, and then get on with the build."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Constituent and household modelling","x":"How people, households, organisations and relationships are represented, decided before anything is built. Almost every painful nonprofit implementation traces back to this being settled late."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Fundraising process design","x":"Gift entry, recurring giving, designations, soft credits, acknowledgement and receipting, built to your actual finance process rather than to a reference diagram."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Programmes, cases and outcomes","x":"The delivery side modelled properly, including the sharing and confidentiality rules that client data in social services requires. This is where most partners stop and we do not."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Licensing and the Power of Us discount","x":"Working out what you are actually entitled to, what the ten donated licences do and do not cover, and what the real annual cost looks like before you commit."},{"p":"nonprofit-cloud","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Tell us who your supporters are.","x":"How you model people, households and giving decides most of what follows. It is worth an hour before anyone opens a builder. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Pipeline you can trust, not pipeline you can report on.","x":"Most Sales Cloud problems are not configuration problems. They are agreement problems: nobody ever wrote down what a stage means, so the forecast is a feeling with a number attached. We fix the definitions first and the object model second. Each stage is a test something has to pass, not a mood. That is the whole difference between a forecast you can defend and one you re-explain every month."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Three things break in almost every org we open.","x":"None of them are exotic. They are the ordinary consequences of a system that was configured quickly, then never revisited while the business changed underneath it."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Stages anyone can game","x":"When a stage means whatever the rep says it means, the pipeline inflates quietly and the correction always arrives at quarter end. We rewrite stages as evidence tests and let the data enforce them."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"A forecast assembled in a spreadsheet","x":"If your forecast is rebuilt by hand every Monday, Salesforce is not your forecasting system, it is your data entry system. We move the calculation back into the platform so the number and the pipeline cannot disagree."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Quoting that leaves the building","x":"Quotes done in a spreadsheet and emailed as a PDF take the margin, the version and the approval trail with them. We bring quoting back onto the record, with the pricing rules your finance team actually enforces."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Sales Cloud is enough when","x":"You sell a reasonably stable set of products, discounting is a conversation rather than a ruleset, and the quote is a document rather than a contract with schedules. Most New Zealand mid-market sales teams sit here, and adding more product is a cost with no return."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"You need more when","x":"Pricing depends on configuration, contracts renew and amend on their own cycle, or revenue has to be recognised over time. That is Revenue Cloud territory, and with Salesforce CPQ now end-of-sale it is worth deciding deliberately rather than inheriting a product."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"A fortnight in your pipeline","x":"We sit with the people who use it, not only the people who report on it. Most of what is wrong is visible in the first week and admitted in the second."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Stage definitions on one page","x":"Written in your language, agreed by sales and finance together, and short enough that a new rep can read it in their first hour."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Build to the definitions","x":"Validation, required evidence, forecast categories and reporting follow from the definitions. This is the fastest part, because the argument already happened."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Then keep going","x":"Sales process is never finished, because the market is not. Most clients carry this on through Waypoint rather than waiting for the next big project."},{"p":"sales-cloud","t":"Sales Cloud consultants, New Zealand | Enable","h":"Show us your pipeline and we will tell you what we see.","x":"A first conversation costs nothing and is usually uncomfortable in a useful way. If Sales Cloud is not your problem, we will say so. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Every case has a clock on it. Most orgs cannot see the clock.","x":"Customers do not experience your queue depth, they experience the wait. Service Cloud is good at measuring both, and most implementations measure neither, because routing was set up once and entitlements never were. Nothing here is a bug. Every step worked as configured. The design simply never decided who was responsible on a Friday evening."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Service problems are rarely about effort.","x":"Support teams are usually working harder than the org deserves. The cost is almost always in the handoffs, the re-explaining, and the things nobody wrote down."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Routing that ignores skill","x":"Round-robin is fair to the roster and unfair to the customer. Omni-Channel can route on skill, language, product and capacity, and most orgs are paying for that and using none of it."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Knowledge nobody trusts","x":"An article written once in 2022 and never reviewed is worse than no article, because people find it and believe it. Knowledge needs an owner and a review date or it quietly becomes misinformation, including for your agents."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"SLAs that exist only in the contract","x":"If the entitlement is not modelled in the platform, nobody knows a clock is running until it has already stopped. Milestones are unglamorous and they change behaviour more than any dashboard."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Before you put an agent in front of customers.","x":"Agentforce Service is genuinely good, and it is not a way around an unclear process. An agent trained on knowledge nobody trusts will answer confidently and wrongly, at a speed no human could manage."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Decide what it may not do","x":"The useful question is not what the agent can answer, it is what it must hand over. Write the escalation rules before the happy path, because that is where reputational damage actually happens."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Ground it in something real","x":"Grounding is a data problem, not a prompt problem. If your knowledge and case history are inconsistent, the agent inherits the inconsistency and states it with confidence."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Test it like a release","x":"Agents regress when the underlying data changes, not when the code does. That needs a held-out set of real questions and a rerun every time you change grounding."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"We follow ten real cases","x":"End to end, from whatever the customer actually did first. Ten is enough to see the pattern and few enough to read every line."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Map where the time goes","x":"Almost never in the work. Usually in waiting, reassignment, and asking the customer something they already told you."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Fix routing and entitlements first","x":"These are the changes customers feel in the first fortnight, and they cost less than anything with AI in the name."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Then automate what is now stable","x":"Deflection, knowledge and agents are worth doing once the process underneath them is worth repeating."},{"p":"service-cloud","t":"Service Cloud consultants, New Zealand | Enable","h":"Let us follow ten of your cases.","x":"Give us read access and a fortnight, and we will show you where the time actually goes. It is usually not where the dashboard says. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"One person, spelled six different ways.","x":"Data 360 is where the arguing stops. Not because it is clever, but because it forces you to decide what a customer is, which system is right when two disagree, and what you will do about the records that match on nothing. Four records, one supporter, no shared key. Identity resolution is a set of rules someone has to own, not a switch you turn on."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"The hard part is never the pipes.","x":"Connecting a source system is a morning. Deciding that a date is a date and a person is a person, regardless of which system spelled it which way, is the project."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Harmonisation is a series of decisions","x":"Every mapping is someone choosing which system wins. Done by an integrator alone, those choices are invisible and surface a year later as a number nobody believes. We make them in the open, with the people who own the data."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Identity resolution has no right answer","x":"Match too loosely and you merge two real people. Match too tightly and your best supporter looks like four strangers. The ruleset is a business decision about which error you would rather explain."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Grounding is only as good as the above","x":"Every agent that answers from your data inherits whatever you decided here. This is why we will not start an Agentforce build on a data layer nobody has audited."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Let us talk about credits, because nobody else will.","x":"Data 360 is consumption priced, and the bill is driven by choices made during the build: how often you ingest, how much you harmonise, how wide your identity ruleset reaches and how often insights recalculate."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"We model the cost before the build","x":"A consumption estimate is part of the design, not a surprise after go-live. If the number is uncomfortable, it is far cheaper to find that out on a whiteboard."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Zero copy where it earns its place","x":"If the data already lives in Snowflake, BigQuery or Databricks and nobody needs it resident, federating beats copying. Sometimes. It is a real trade-off, not a slogan."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Ingest what you will use","x":"The most common waste we see is streaming everything because it was easy, then paying to store and process fields no segment has ever referenced."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Profile the sources honestly","x":"Before any modelling, we look at what is actually in the fields. This is the step that gets skipped, and it is the step that predicts the whole project."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Agree the survivorship rules","x":"Which system wins for a name, an address, a consent flag. Written down, signed off, and revisited when it turns out to be wrong."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Resolve, then measure the errors","x":"We look at what merged that should not have, and what stayed apart that should not have. Both lists matter, and only one of them is comfortable reading."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Only then, activate","x":"Segmentation, insights and agent grounding are the easy end. They are also where a bad foundation becomes visible to customers."},{"p":"data-360","t":"Data 360 consultants, New Zealand | Enable","h":"Bring us your worst duplicate.","x":"The one everybody in the office knows by name. It usually explains the whole data estate in about twenty minutes. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"The work happens in Slack. The record lives in Salesforce.","x":"Most organisations have already decided where their people talk, and it is not the CRM. The question worth asking is whether the decisions made in that conversation ever reach the record, or evaporate when the channel scrolls. Two of these reached the record because someone built for them. The other two are the reason your pipeline review still relies on memory."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Slack is a surface, not a second system of record.","x":"The failure we see most often is treating Slack as somewhere to post notifications. Nobody reads a channel that only ever shouts at them."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Make the record editable from the conversation","x":"Salesforce Channels let a deal, a case or a project live alongside the discussion about it, and be updated without a context switch. That is the whole trick: remove the tab change and the data arrives on its own."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Put the agent where the question is asked","x":"People ask colleagues before they search a knowledge base. An Agentforce agent in the channel answers where the question was already going to be asked, which is the only place adoption comes free."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Automate the small repeated asks","x":"Workflow Builder handles the requests that clog a channel: access, approvals, onboarding steps, the same form somebody pastes every week. Unglamorous, and it buys back real hours."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Governance, before it becomes an audit finding.","x":"Slack Connect with suppliers and partners is enormously useful and quietly changes who can see what. Retention, DLP and eDiscovery are cheap to set up early and painful to retrofit after two years of history."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Who is actually in this channel","x":"External members in a Connect channel are easy to forget and easy to over-share with. Naming conventions and a review cadence cost nothing and prevent the conversation you never want to have."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"What is kept, and for how long","x":"Retention is a legal decision made by default if nobody makes it deliberately. Decide it once, per channel type, and let the platform enforce it."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Find where the record and the talk diverge","x":"Usually one or two moments in a process where a decision is made in conversation and never written down. Those are worth more than a Slack rollout plan."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Link one object properly","x":"One process, done well, in channels people already use. Adoption is evidence, not a change management programme."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Add the agent once there is something to ask it","x":"An agent with nothing reliable to answer from teaches people to ignore it, and they will not come back for the second version."},{"p":"slack","t":"Slack and Salesforce consultants, New Zealand | Enable","h":"Where does your process leave Salesforce?","x":"It is almost always the same two or three moments. Show us one and we will show you what it costs you. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Software for people whose office is a paddock.","x":"The primary sector runs on seasons, not quarters. Cashflow arrives in lumps, the same person is a supplier and a shareholder, and half the work happens where there is no signal. Systems designed for city businesses fail in ways that look like user error. Model this as four contacts and every conversation starts with the grower correcting you. Model it once, properly, and the relationship is finally legible."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"The sector is not hard because it is rural.","x":"It is hard because the relationships are genuinely more complicated than the data models most software ships with, and because the consequences of getting it wrong land on people you will see at the saleyards."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"One party, several hats","x":"Supplier, shareholder, customer and debtor are frequently the same family entity across several trusts. Standard account hierarchies bend badly here, and the workaround usually becomes permanent."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"A year that is not four equal quarters","x":"Calving, harvest, shearing and payout cycles drive when money and attention exist. Forecasting and service coverage built on even quarters will be wrong twice a year, predictably."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Compliance that keeps arriving","x":"Farm environment plans, freshwater rules, emissions reporting and traceability keep adding obligations. The organisations coping well treat evidence capture as part of the normal workflow rather than an annual scramble."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Agritech companies building a product","x":"If you sell software or services to farmers, your Salesforce problem is usually onboarding, support at scale and understanding which customers are actually getting value. We work on the commercial platform behind the product, and we know better than to redesign your product."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Primary sector organisations","x":"Co-ops, processors, rural service businesses and industry bodies. Here the work is usually making one grower legible across supply, shares, trade and compliance, which is a data modelling job long before it is a CRM job."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Map one grower end to end","x":"Every relationship they have with you, every system that holds part of it. This is usually the first time anyone has drawn it on a single page."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Decide what an entity is","x":"Farm, family, trust, supply number, shareholding. Getting this wrong is the single most expensive mistake in the sector and it is very hard to unwind later."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Build for the season, not the quarter","x":"Forecasts, service coverage and campaign timing follow the production calendar, because that is when your customers have time and money."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Then keep improving it","x":"Rules change, and they change on the government cycle rather than yours. Waypoint is how most clients absorb that without a new project each time."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"We work in this sector, and we are not going to overstate it.","x":"Enable has delivered for a New Zealand agritech company, and that engagement is written up on our work page as a draft until the client has reviewed and approved what it says. We would rather show you an unfinished page than a polished claim nobody has checked. Ask us in a call and we will tell you exactly what we have and have not done."},{"p":"agritech","t":"Agritech and primary sector Salesforce partner | Enable","h":"Draw us your most complicated grower.","x":"The one with three trusts, two supply numbers and a shareholding. If we can model that on a whiteboard with you, the rest of the project is arithmetic. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"Funding is not revenue. Your CRM should know the difference.","x":"A donation has conditions, a grant has milestones, a bequest arrives years after the relationship that earned it, and a volunteer may also be a donor and a service user. Systems built for sales treat all of this as an opportunity, and the reporting never recovers. The bequest was earned by the volunteering. If your system cannot show that, your board will keep funding the channel that looks cheapest this quarter."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"What we have actually done in this sector.","x":"Two named organisations, both willing to be talked about. We would rather show you two real engagements than a logo wall you cannot ask questions about."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"Heritage New Zealand Pouhere Taonga","x":"Six systems holding fragments of the same supporter, resolved into one profile in Data 360. Membership, ticketing, retail, donations and property visits harmonised so a person is a person regardless of which system spelled it which way."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"Hato Hone St John","x":"Standing up an AI-assisted way of working with their delivery teams, so ideas reach something running in a fraction of the time. The capability stayed with their people, which was the point."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"The three conversations that come up every time.","x":"None of them are technology questions, and all of them decide whether the technology was worth buying."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"What counts as a supporter","x":"Households, organisations, whanau and individuals all matter differently depending on whether you are thanking, reporting or asking. Deciding this once, deliberately, prevents a decade of reconciliations."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"Restricted funds are a promise","x":"Designations, soft credits and grant conditions are commitments to a funder, not reporting categories. Modelled properly they make acquittal routine. Modelled badly they make it a fortnight of spreadsheets."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"Outcomes, not only outputs","x":"Funders increasingly want to know what changed, not how many sessions ran. That is a measurement design problem you want to solve before the next funding round, not during it."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"There is a decision to make, and a deadline behind it","x":"Nonprofit Cloud is where Salesforce is investing, and NPSP is not the long-term destination. That does not mean migrating this year, but it does mean choosing deliberately rather than discovering the timeline late."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"We sell the assessment separately, on purpose","x":"A migration assessment that can only conclude yes is not an assessment. Some organisations should stay put for now, and we would rather be paid to tell you that than paid to move you."},{"p":"nonprofit","t":"Nonprofit Salesforce partner, New Zealand | Enable","h":"Tell us what your board asks for that you cannot answer.","x":"It is usually one number, requested every quarter, assembled by hand. That question is the fastest route to understanding the whole system. Ten Power of Us licences are free to eligible nonprofits. No lock-in contracts, non-competes or minimum terms. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Advice you can evidence, years after you gave it.","x":"In financial services the record is not administration, it is the defence. What was recommended, what the client was told, what they understood and what they chose. Most systems capture the outcome and quietly lose the reasoning. The last line is the one a complaint turns on. Capture is a design decision, and it has to be made before you need it."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Why the standard data model matters more here.","x":"Financial Services Cloud exists because households, entities, relationships and financial accounts do not fit a contact and an opportunity. Rebuilding that yourself is possible, expensive, and hard to explain to an auditor."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"A client is usually several parties","x":"Individuals, trusts, companies and the relationships between them. Advice is given to a household as often as a person, and the obligations attach to both."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Reviews are obligations, not campaigns","x":"A scheduled client review that quietly slips is a compliance event, not a missed marketing touch. Modelled as an obligation, the platform can prove it happened."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Every interaction may be evidence","x":"Calls, emails, documents and the adviser note that explains the decision. If capture depends on discipline rather than workflow, it will be uneven in exactly the files you later need."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"New Zealand specifics we design around.","x":"The regime here is its own thing, and overseas templates need real adaptation rather than a relabelling exercise."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Financial advice obligations","x":"Licensing, duties to clients and record keeping under the FMA regime shape what the system has to be able to produce on request, and how long it must keep it."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"AML and CFT","x":"Customer due diligence, beneficial ownership and ongoing monitoring generate data with retention rules and access restrictions of their own. Getting sharing wrong here is a different class of problem."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Complaints and dispute resolution","x":"A complaint has a clock, a defined process and an external scheme behind it. Handling it in email is common, and indefensible once it escalates."},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"We have a financial services client. The write-up is not finished.","x":"Enable works with UDC Finance, New Zealand\u2019s finance company, across Marketing Cloud Next and Salesforce Intelligence on a Data 360 foundation. Their case study is deliberately thin, because UDC has not yet reviewed a written account of the work and we will not publish one they have not read. Beyond that engagement we are still building this practice: we bring deep platform, data and compliance-adjacent experience, and we will be explicit about where we are learning your regime rather than teaching it. Ask in the f"},{"p":"financial-services","t":"Financial services Salesforce partner, New Zealand | Enable","h":"Pick an advice file from three years ago.","x":"If you can reconstruct what was recommended and why, you are in better shape than most. If you cannot, that is the project. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"An enquiry about a parent is not a sales lead.","x":"Somebody is ringing because a situation at home has changed, often suddenly, and usually on behalf of someone else. Treat that as a lead to be worked and you will be efficient, fast and remembered for the wrong reasons. One enquiry, four people, one of whom will live there. Systems that store a single contact make the family repeat themselves at the worst possible time."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"We have done this work, in retirement living.","x":"Real Living came to us because every enquiry, for every village, was reaching one person. Not by design, by a routing fallback nobody had looked at since it was built."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"What was actually wrong","x":"A queue-fallback label meant enquiries for one village were landing with a single coordinator regardless of where the family was looking. Fixing it was a small change, and finding it required reading the routing rather than the reports."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Where retirement living and aged care differ","x":"Independent and assisted living is close to, but not the same as, hospital level residential care. The enquiry journey and family dynamics carry across. Clinical systems, funding and audit obligations do not, and we will not pretend otherwise."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"The patterns that decide whether the system helps.","x":"Aged care and retirement living have a small number of structural facts that most CRM implementations ignore, and each one shows up later as a complaint."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"The enquirer is rarely the resident","x":"Relationships have to be first-class: who called, who decides, who pays, who holds power of attorney. If the model cannot hold that, your team will keep it in their heads and it will leave when they do."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Availability changes the conversation","x":"A family looking at a village with nothing available needs different handling from one with a unit ready next month. Waitlists that are not visible in the enquiry process turn into promises nobody can keep."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Care needs escalate, usually quickly","x":"A move from independent to assisted to hospital level is a change in almost every record you hold. Designing for that transition beats designing for the tidy initial state."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Ring your own enquiry line","x":"We do this on nearly every engagement. Twenty minutes as a family member tells you more than a month of reporting."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Follow the enquiry to whoever it reached","x":"Including the ones that reached nobody. The gaps are the finding, and they are almost always in routing rather than effort."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Model the family, not the contact","x":"Relationships, decision rights and the paperwork trail. This is the change your teams will feel first."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Then keep it honest","x":"Village teams change, sites open, rules move. Waypoint is how most clients keep the system matching the operation."},{"p":"aged-care","t":"Aged care and retirement living Salesforce partner | Enable","h":"Ring your own 0800 number this afternoon.","x":"Then tell us what happened. If it went where you expected, we will say so and charge you nothing for the conversation. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"A student is not a contact with a different record type.","x":"They are a prospect, an applicant, an enrolled learner, a graduate and an alumnus, often with gaps of years between. Most education systems model the enrolment and lose the person on either side of it. Four systems, one person, no shared identity. The advancement team is asking a stranger for money, and the data to know better already exists."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"The lifecycle is the hard part.","x":"Recruitment, enrolment, support and advancement are usually run by different teams with different systems and different definitions of the same learner. Nobody set out to build it that way."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"Recruitment that knows the history","x":"A prospect who deferred last year, or whose sibling studied with you, is not a cold lead. Treating them as one is both expensive and slightly insulting."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"Student success needs early signals","x":"Attendance, engagement and support contacts predict withdrawal far earlier than results do. Bringing them together is a data problem the student system alone rarely solves."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"Advancement starts before graduation","x":"The relationship that produces a gift or a placement began while they were studying. If the record starts at graduation, you are rebuilding a relationship you already had."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"We are not here to replace it","x":"Your SMS holds enrolment, academic records and timetabling, and it should. The useful work is usually at the edges: recruitment, engagement, support and advancement, with identity resolved across all of them."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"Integration is the deliverable","x":"Which system owns a learner identity, what syncs, what federates and what stays where it is. Answered deliberately, this is a sound architecture. Answered by accident, it is the reason nobody trusts the numbers."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"An emerging practice, stated plainly.","x":"Enable works across the Salesforce platform, and education is a sector we are moving into rather than one where we can hand you a list of New Zealand institutions we have delivered for. We know Education Cloud, the lifecycle and the integration patterns. We do not yet have the sector reference you may reasonably want. If that matters for your procurement, say so early and we will tell you honestly whether we are the right fit."},{"p":"education","t":"Education Salesforce partner, New Zealand | Enable","h":"Ask your advancement team who their best prospect is.","x":"Then ask whether your recruitment team ever met them. The gap between those two answers is usually the business case. No lock-in contracts, non-competes or minimum terms. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Moving from the Nonprofit Success Pack to Nonprofit Cloud.","x":"NPSP remains supported and Salesforce has announced no forced end date. That makes this a decision rather than a deadline, which is the best possible time to make it carefully. Start with an assessment, not a migration plan. The model underneath is different, which is why this is a rebuild rather than a data load."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Where we stand on this","x":"Enable has years of Salesforce nonprofit experience and delivers Nonprofit Cloud today. NPSP migration is an offering we are bringing to market now, rather than a decade-long track record we are going to claim. What that means in practice: the assessment is priced small and sold on its own, the findings are yours whether or not you continue, and we will tell you plainly where the ground is new for everyone."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"The first question is whether to move at all","x":"Plenty of organisations are running NPSP well and should keep doing so for now. The cost of moving is real, and a migration undertaken because of a rumour about end-of-life is a migration done for the wrong reason."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Reasons to move now","x":"You need programme, case or outcome management and are currently bolting it on. You are buying new Salesforce capability that assumes core objects. Your customisation of NPSP has become the thing that blocks every upgrade."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Reasons to wait","x":"NPSP is doing what you need, your customisation is light, and the money would do more good spent on the mission this year. Waiting is a legitimate answer and we will give it where it is the right one."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Reasons it is not the real problem","x":"If reporting is wrong, adoption is poor or data quality is bad, those follow you across. A migration is an expensive way to discover that the problem was the process. We would rather find that first."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"What actually changes","x":"Not a rename. The data model underneath is different, which is why a migration is a rebuild of your fundraising operation rather than a data load."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Three weeks, fixed price","x":"Priced small and deliberately separate, so you can stop after it without having bought a migration."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"What we look at","x":"Your NPSP customisation, data volumes and quality, integrations, reporting, recurring giving setup, and what your team actually uses day to day."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"What you get","x":"A written recommendation with a real number: move, wait, or fix something else first. Plus a sequenced plan if the answer is move, and the findings to act on yourself if it is not."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Model first, migrate second","x":"Constituents, households, designations and recurring giving modelled in a sandbox and tested against your real data before anything is committed. The model is the migration."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Run in parallel where it is possible","x":"Financial year boundaries, appeal cycles and audit periods decide the cutover, not the project plan. Where a parallel period is feasible we use it."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"History, receipting and the audit trail","x":"Gift history, acknowledgements and the numbers your auditor and your funders rely on, reconciled before cutover rather than explained afterwards."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Start with the question, not the migration.","x":"Tell us what is not working in NPSP today. Often the answer is a fix rather than a move, and that is a much cheaper conversation to have first. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Marketing Cloud Next, from the first partner in APAC to deliver it.","x":"Campaigns on the core platform: audiences from Data 360, journeys built in Flow, and measurement that does not need a separate warehouse. We were first in the region to ship it and have been through seven implementations since. Audience, journey, send, branch and reply all in one org. The report does not begin with an export."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"What it is, as a product","x":"Marketing Cloud Next is not the old Marketing Cloud with a new badge. It runs on the core platform, which changes what a campaign can see and what it can trigger."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Journeys built in Flow","x":"The same Flow your admins already know, not a separate journey canvas with its own logic and its own outages. A journey can call anything the platform can do."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Content and channels","x":"Branded email and content on the platform, plus SMS, WhatsApp and push. Sender setup, templates and reusable content blocks that marketers maintain themselves."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Segments from Data 360","x":"Audiences built on the unified profile rather than on a list someone exported. Membership updates as the data does, so a segment is a rule, not a snapshot."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Agentforce inside the campaign","x":"Agents that answer the reply, qualify the response and pick up the conversation the campaign started, grounded in the same records."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Data 360, the audience layer","x":"Identity resolution, unified profiles and calculated insights. A segment is only ever as good as the resolution underneath it, and most campaigns that misfire, misfire here rather than in the creative. We model the credits before you commit, because consumption is where these programmes get expensive."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Personalisation, the moment","x":"Real time means acting on behaviour as it happens: a browse, an abandoned form, a change in the profile. Not a list assembled three weeks after the moment has passed. This is the difference between personalisation and a mail merge, and it is the reason the platform sits where it does."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Intelligence, the measurement","x":"Engagement scoring, Einstein assists and attribution that runs back to pipeline or to giving in the same org. Because it is one platform, the report does not begin with an export, which is usually where marketing measurement quietly stops being trusted."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Migrating from Marketing Cloud Engagement or Pardot","x":"Most estates we look at carry a decade of journeys, half of which nobody has switched off. The migration is an opportunity to stop running those, and the plan should say so out loud."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Decide what actually moves","x":"An inventory of every journey, automation and send, with an owner and a last-run date against each. A surprising amount of it gets retired rather than rebuilt, and that is the cheapest win available."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Data and consent before anything else","x":"Subscriber data, preference centres, consent records and suppression lists reconciled first. Getting consent wrong in a migration is the one mistake with a regulator attached to it."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Deliverability and authentication","x":"SPF, DKIM, DMARC, sending domains and IP warm-up planned before the first production send. Sending reputation takes months to build and one bad weekend to lose."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Parallel run, then switch","x":"Both platforms live, results compared on real sends, then cut over. We do not do big-bang marketing migrations, and we will not lift a broken journey across so it can keep being broken."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"What are you sending today, and what is it doing?","x":"Bring the journey inventory if you have one. If you do not, that is usually the first thing worth building, and it is often where the business case comes from. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work","t":"Our work, described honestly | Enable","h":"The work, described honestly.","x":"Five engagements, written up without the numbers we cannot verify and without detail the client has not yet agreed to. What is here is what was actually built, what it actually changed, and which products it was built on. We will introduce you to a client who will talk to you. That is worth more than a logo wall."},{"p":"work","t":"Our work, described honestly | Enable","h":"Five engagements","x":"The products listed on each are the ones actually used, confirmed by us rather than inferred from the write-up."},{"p":"work","t":"Our work, described honestly | Enable","h":"Six systems, one supporter","x":"A supporter who joins, gives, visits a property and buys in the shop was five records in five places. Unified on Data 360, in production."},{"p":"work","t":"Our work, described honestly | Enable","h":"Every enquiry reached one person","x":"Strong enquiry volume, all landing in one consultant\u2019s queue because of a routing fallback nobody had revisited since go-live."},{"p":"work","t":"Our work, described honestly | Enable","h":"Marketing, measured properly","x":"New Zealand\u2019s finance company, across Marketing Cloud Next and Salesforce Intelligence on a Data 360 foundation. Engagement detail to come."},{"p":"work","t":"Our work, described honestly | Enable","h":"Teams that ship faster, with AI in the loop","x":"Rapid AI-assisted development practice stood up with their teams, so delivery moves at a different pace and the capability stays in-house."},{"p":"work","t":"Our work, described honestly | Enable","h":"Agri-tech, on Salesforce","x":"Farm financial software for New Zealand and Australian farmers, across the front office and the data underneath it. Engagement detail to come."},{"p":"work","t":"Our work, described honestly | Enable","h":"Why two of these are still drafts","x":"Heritage New Zealand, Real Living and Hato Hone St John are named with their agreement, and their pages carry the detail. Farm Focus and UDC Finance are marked as drafts because neither has yet reviewed a written account of the work, and putting words in a client\u2019s mouth on a marketing page is a strange way to demonstrate that you can be trusted with their data. As each one says yes, the detail goes up. Ask us and we will put you on a call with someone who has worked with us."},{"p":"work","t":"Our work, described honestly | Enable","h":"Want to talk to one of them?","x":"We will make the introduction. No sales call in between, and you can ask them whatever you like, including what went wrong. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Heritage New Zealand can see the whole relationship, not a fragment of it.","x":"A supporter who joins, gives, visits a property, books an event and buys something in the shop used to be five records in five places. Enable unified them on Data 360 and put the resulting profile in front of the people who need it, in production."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"The organisation","x":"Heritage New Zealand Pouhere Taonga is the Crown entity responsible for identifying, protecting and promoting New Zealand\u2019s historic places. It cares for properties the public visits, maintains the national list of heritage places, and is supported by members, donors and volunteers. That breadth is the interesting part. The same person might hold a membership, give to an appeal, walk through a property on a Sunday, book a school visit, send an enquiry about a listing, and buy a book in the shop. Six relationships, "},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"The situation","x":"Every one of those interactions was being recorded. None of them were being recorded together. Answering a question as ordinary as \u201chas this person supported us before\u201d meant opening several systems and making a judgement call about whether three similar-looking records were the same person. Everyone knew this. What did not exist was a route through it that began with a multi-year data warehouse programme, which for a Crown entity with public funding is a hard thing to justify and a harder thing to finish."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Modelled to the standard data model","x":"Source systems mapped onto the Customer 360 data model rather than a bespoke schema. That decision is unglamorous and it is the one that decides whether the thing still makes sense to the next person who touches it, or needs remapping every time a source changes."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Ingestion and harmonisation in Data 360","x":"Memberships, donations, event bookings, property visits, enquiries and retail brought into Data 360 and harmonised, so that a date is a date and a person is a person regardless of which system spelled it which way."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Identity resolution tuned against real records","x":"A ruleset built and tested on the actual data, including households, shared email addresses, and people who have been in the database since the nineties under three spellings of the same name. Match results were reviewed with staff who know the constituents, not signed off against a metric."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Unified profile activity","x":"The engagement history brought together so a single view shows what a person has actually done, in order, regardless of which system recorded it. This is the part users notice, and the part that makes the rest of the work legible to people who were never going to read a data model."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Surfaced where the work happens","x":"The unified profile exposed on the records staff already use, rather than in a separate analytics tool nobody opens. A capability that requires a second login is a capability that gets used twice."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Deployed to production, with tests","x":"Apex covered per class and deployed against the production org with specified tests, not left as a sandbox proof of concept for someone to productionise later. Production is where this either works or does not."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"The question is answerable","x":"\u201cHave we talked to this person before, and about what?\u201d is now one screen instead of three people checking three systems and comparing notes in a meeting."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Data quality became visible","x":"Resolution surfaces the duplicates everyone suspected and nobody could count. That is uncomfortable and useful in roughly equal measure, and it gives the next cleanup an actual target."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"A foundation, not an endpoint","x":"Segmentation, agent grounding and personalisation all need a resolved profile underneath them. Building it first makes every one of those conversations shorter, and cheaper."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"What we would tell you","x":"Identity resolution is where this kind of project succeeds or quietly fails, and it cannot be done well from a spreadsheet of field mappings. Budget real time for sitting with the people who know the constituents. They will spot a bad match in a second that a rule would have accepted forever. Data 360 consumption is real money. We would rather model it with you before you commit than explain the bill afterwards, and for a publicly funded organisation that conversation needs to happen in writing, early. And a produc"},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Recognise any of this?","x":"If your supporters turn up in six systems and none of them agree, the first conversation is free and usually tells us both whether there is a project here. Published with Heritage New Zealand Pouhere Taonga\u2019s agreement. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Every enquiry was reaching the same person.","x":"Real Living was generating strong enquiry volume across several villages. Almost all of it was landing in one consultant\u2019s queue, because of a routing fallback nobody had revisited since go-live. The rules read correctly. A fallback written as a safety net had become the main path."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"The situation","x":"Marketing was working. Enquiries were arriving. But follow-up was slow and uneven, and leadership could not see why. The routing rules looked correct on paper. What had happened was more ordinary: a fallback assignment, written as a safety net at go-live, had quietly become the main path, because several village-level users had been deactivated over the years and duplicates created in their place. Every enquiry that failed to match an active user fell through to the same queue and the same person."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Traced the routing, not the symptom","x":"The reported problem was slow follow-up. The actual problem was assignment. We followed real enquiries through the rules rather than reading the configuration and assuming it did what it said."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Rebuilt assignment around the village","x":"Routing keyed to the village the person is enquiring about, with an owner per village and a fallback that alerts somebody rather than silently absorbing the work."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Cleaned up the user estate","x":"Inactive users and their duplicates identified and resolved, which is unglamorous and was the actual root cause."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Made tours visible on the account","x":"Tour bookings were being recorded against a child object that the account page never showed, so a booked visit was invisible to anyone looking at the person. We surfaced it, and fixed a re-entrant save loop found along the way."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Enquiries reach the right village","x":"Follow-up is now done by the person who knows the site the enquirer is asking about, which changes the quality of the conversation as much as the speed."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"One consultant got their week back","x":"The person absorbing the fallback was carrying work that was never meant to be theirs, and no report showed it."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Leadership can see the funnel","x":"Enquiry through to tour through to outcome, per village, from records rather than from a manually maintained spreadsheet."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"What we would tell you","x":"Nobody had done anything wrong here. A sensible safety net at go-live became the default path over several years of ordinary staff turnover, and no report was looking at assignment. It is worth someone checking routing fallbacks annually, which is exactly the kind of thing a quarterly platform review catches."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Recognise any of this?","x":"If it sounds like your org, the first conversation is free and usually tells us both whether there is a project here. Client withheld pending consent. Happy to make an introduction on request. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"[HEADLINE: what changed for Farm Focus]","x":"[ONE PARAGRAPH: what Enable did and what it made possible. Everything on this page below the organisation section is waiting on the engagement detail. Tell me what the work was and this gets written properly.] The organisation section below is researched and accurate. The rest needs you."},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"The organisation","x":"Farm Focus makes farm financial management software for New Zealand and Australian farmers and growers: cashflow planning, GST returns, livestock reconciliation and reporting, in one place. It began in 1981 when three Wairarapa farmers wanted a better way to forecast a farm business, and the product that came out of it, Cash Manager, ran for forty years before the company rebranded to Farm Focus in 2021. It is based in Masterton and serves thousands of customers across sheep, beef and dairy, from single operators t"},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"This page is unfinished","x":"The organisation section above is researched from public sources and accurate. Everything else is a placeholder, because inventing work Enable did for a named New Zealand company is the one mistake this page cannot recover from. What is needed: what the engagement actually was, which part of the platform it touched, roughly when, and what changed as a result. Four sentences is enough to write the rest. Until then this page should stay unpublished and its card removed from the index."},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"[CTA HEADLINE]","x":"[One or two sentences inviting the reader with a similar problem to get in touch.] Draft. Not for publication until the engagement detail is confirmed. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Building teams that ship faster, with AI in the loop.","x":"Hato Hone St John wanted delivery to move at a different pace. Enable worked with their teams to stand up rapid AI-assisted development practice: not a tool rollout, but a way of working that gets from idea to something running in a fraction of the time. The grey row is a number only Hato Hone St John can give us. Everything above it is checkable."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"The organisation","x":"Hato Hone St John has been operating in New Zealand since 1885. It is a charity, it employs and enrols many thousands of paid staff and volunteers, and it provides the overwhelming majority of the country\u2019s emergency and non-emergency ambulance coverage, alongside first aid training, event medical cover, community health programmes and support lines for people living alone. That is a wide operational surface, and it is one where software delays have a cost that is not measured in revenue. Technology that takes eigh"},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"The situation","x":"The teams were capable and the backlog was longer than the delivery capacity, which is the ordinary condition of almost every in-house technology function. The question was not whether people were working hard. It was whether the way work moved from idea to running software could be changed at all, rather than simply resourced harder. AI tooling was the obvious lever and also the obvious trap. Handing a team a licence and calling it transformation is how most organisations spend a year discovering nothing changed."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Started with how work actually moves","x":"Before any tooling, we followed real work through the current process: where it waited, where it was rewritten, where a decision took three weeks because the right four people were never in the same conversation. Speed problems are usually queueing problems wearing a technical costume."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Stood up rapid development teams","x":"Small teams set up to go from a stated problem to something running, with AI assistance built into the loop rather than bolted on at the coding step. Scoping, drafting, reviewing and testing all change when the cost of a first version falls."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Built the judgement, not just the habit","x":"The hard part of AI-assisted delivery is knowing when to trust the output and when not to. We worked on review practice, on what gets checked and by whom, and on where a human has to stay in the loop regardless of how convincing the draft looks."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Left the capability with their teams","x":"The measure of this work is that it keeps going without us. Practice documented, patterns written down, and the people who will run it afterwards involved from the first week rather than briefed at the end."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"From idea to running, faster","x":"The gap between someone describing a need and someone using the result closed materially. That shift compounds: shorter cycles mean more attempts, and more attempts mean better answers."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Fewer things waiting","x":"A lot of the gain was not in writing code faster. It was in the queue before the code, where work sat waiting on a decision, a spec or a review."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"The teams own it","x":"The practice sits with Hato Hone St John, not with a partner they have to re-engage to keep it running. That was the point of the engagement rather than a nice side effect."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"What we would tell you","x":"Rapid AI development is a ways-of-working change that happens to involve tools. Organisations that buy the tools and skip the working practice get a faster first draft and the same delivery date, because the bottleneck was never typing. Review discipline matters more, not less. When output is cheap and plausible, the scarce thing is the judgement to reject it. Build that explicitly or it will not happen. And in an organisation where the work is clinical and operational rather than commercial, \u201cmove fast\u201d needs a cl"},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Delivery not moving at the pace you need?","x":"If your teams are capable and the backlog still grows, the constraint is usually in how work moves rather than how hard people work. That is a conversation worth having. Published with Hato Hone St John\u2019s agreement. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"Marketing, measured properly.","x":"Enable works with UDC Finance, New Zealand\u2019s finance company, across Marketing Cloud Next and Salesforce Intelligence on a Data 360 foundation."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"The engagement detail is not here yet, and we are not going to invent it.","x":"UDC has not yet reviewed a written account of this work, so this page says only what we can stand behind: who we work with and what it is built on. The rest goes up once they have read it and agreed to it. If you want to know what the engagement actually covers before then, ask us in a call and we will tell you."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"What these three products do together.","x":"This is what the combination is for in general, not a claim about what was delivered at UDC. Read it as context for the products listed above."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"Data 360 underneath","x":"A finance customer exists across origination, servicing, collections and whatever the broker channel knows. Data 360 is where those become one person, with the survivorship rules written down rather than assumed."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"Marketing Cloud Next on top","x":"Journeys, consent and campaigns built on that resolved customer rather than on a list export. Consent in particular is a compliance artefact in financial services, not a marketing preference."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"Salesforce Intelligence to measure it","x":"The part most marketing stacks skip: attribution and performance measured against the same customer definition the campaigns were built on, so the numbers and the audience cannot quietly disagree."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"The client reads it first","x":"Every case study on this site is sent to the client before it is published. If they will not put their name to the wording, the wording changes or the page stays a draft."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"No numbers we cannot show our working for","x":"Percentage uplifts are easy to write and hard to defend. If a figure is not measured, it does not appear."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"What went wrong stays in","x":"Engagements have bad weeks. Removing them makes every case study read the same and tells a prospective client nothing."},{"p":"work-udc","t":"Case study: UDC Finance | Enable","h":"Want to know more about this one?","x":"Ask us directly. We can tell you a great deal more in a conversation than we are willing to publish before the client has signed it off. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."}];
  var STOP = {the:1,a:1,an:1,and:1,or:1,of:1,to:1,in:1,on:1,for:1,with:1,is:1,are:1,was:1,be:1,do:1,does:1,
    we:1,you:1,i:1,it:1,that:1,this:1,what:1,how:1,can:1,should:1,our:1,your:1,my:1,at:1,as:1,by:1,from:1,
    have:1,has:1,will:1,would:1,if:1,about:1,me:1,us:1,they:1,there:1,their:1,but:1,not:1,so:1,any:1};

  function toks(str){
    return (str||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/)
      .filter(function(w){ return w && w.length>2 && !STOP[w]; })
      .map(function(w){ return w.replace(/(ies)$/,'y').replace(/(es|s)$/,''); });
  }

  var DF = {}, N = INDEX.length;
  INDEX.forEach(function(e){
    var seen = {};
    toks(e.h+' '+e.x).forEach(function(w){ if(!seen[w]){ seen[w]=1; DF[w]=(DF[w]||0)+1; } });
  });
  function idf(w){ return Math.log(1 + N/(1+(DF[w]||0))); }

  function search(q){
    var qt = toks(q); if(!qt.length) return [];
    return INDEX.map(function(e){
      var h = toks(e.h), x = toks(e.x), ttl = toks(e.t + ' ' + e.p), sc = 0, hit = 0;
      qt.forEach(function(w){
        var inT = ttl.indexOf(w)>=0 ? 1 : 0;
        var inH = h.indexOf(w)>=0 ? 1 : 0;
        var n = 0; for(var i=0;i<x.length;i++) if(x[i]===w) n++;
        if(inT || inH || n){
          hit++;
          // square the idf so a distinctive word like "waypoint" outweighs "actually"
          sc += Math.pow(idf(w), 2) * (inT*4 + inH*3 + Math.min(n,3));
        }
      });
      // answering half the question is worth less than half as much
      return {e:e, s:sc * Math.pow(hit/qt.length, 2)};
    }).filter(function(r){ return r.s > 0; })
      .sort(function(a,b){ return b.s-a.s; }).slice(0,3);
  }

  function snippet(text, q){
    var qt = toks(q);
    var sents = text.split(/(?<=[.!?])\s+/);
    var best = sents[0], bestScore = -1;
    sents.forEach(function(sn){
      var t = toks(sn), sc = 0;
      qt.forEach(function(w){ if(t.indexOf(w)>=0) sc++; });
      if(sc > bestScore){ bestScore = sc; best = sn; }
    });
    var i = sents.indexOf(best);
    return sents.slice(i, i+2).join(' ').trim();
  }

  function el(tag, cls, txt){ var n=document.createElement(tag); if(cls) n.className=cls; if(txt) n.textContent=txt; return n; }

  var STAR = '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'
    + '<path d="M12 2l1.9 6.1L20 10l-6.1 1.9L12 18l-1.9-6.1L4 10l6.1-1.9z"/></svg>';

  function thinking(root){
    var box = el('div','agent-think');
    var stars = el('span','agent-stars'); stars.innerHTML = STAR+STAR+STAR;
    var label = el('span',null,'Reading the site');
    box.appendChild(stars); box.appendChild(label); root.appendChild(box);
    root.scrollTop = root.scrollHeight;
    var lines = ['Reading the site','Finding the passage','Checking what it says'], i = 0;
    var t = setInterval(function(){ i++; if(i<lines.length) label.textContent = lines[i]; }, 620);
    return function(){ clearInterval(t); box.remove(); };
  }

  function followUp(root, asked){
    if(root.querySelector('.agent-followup')) return;
    var box = el('div','agent-followup');
    box.appendChild(el('p',null,'Did that answer it? If you would rather talk it through, leave your details '
      + 'and Blair will come back to you. He replies to everything.'));
    var f = document.createElement('form');
    f.style.cssText = 'display:flex;flex-direction:column;gap:12px';
    [['name','Your name','text'],['email','Email','email']].forEach(function(spec){
      var w = el('div','agent-f-field');
      var l = el('label',null,spec[1]); l.setAttribute('for','af-'+spec[0]);
      var inp = document.createElement('input');
      inp.id='af-'+spec[0]; inp.name=spec[0]; inp.type=spec[2]; inp.required=true; inp.autocomplete=spec[0];
      w.appendChild(l); w.appendChild(inp); f.appendChild(w);
    });
    var w3 = el('div','agent-f-field');
    var l3 = el('label',null,'What are you trying to do?'); l3.setAttribute('for','af-message');
    var ta = document.createElement('textarea'); ta.id='af-message'; ta.name='message'; ta.value = asked || '';
    w3.appendChild(l3); w3.appendChild(ta); f.appendChild(w3);
    var send = el('button','agent-f-send','Send it to Blair'); send.type='submit'; f.appendChild(send);
    var no = el('button','agent-f-no','No thanks, just browsing'); no.type='button';
    no.addEventListener('click', function(){ box.remove(); }); f.appendChild(no);

    f.addEventListener('submit', function(e){
      e.preventDefault();
      // f.name is the form's own name attribute, not the input - go through elements
      var data = new URLSearchParams({ 'form-name':'enable-drawer', name:f.elements.name.value,
                                       email:f.elements.email.value, message:f.elements.message.value,
                                       asked:asked||'' });
      send.disabled = true; send.textContent = 'Sending…';
      fetch('/', {method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'}, body:data.toString()})
        .then(function(){ box.innerHTML='';
          box.appendChild(el('p',null,'That is with Blair. He replies to everything, usually the same working day.')); })
        .catch(function(){ box.innerHTML='';
          var pEl=el('p',null,'That did not send. Email blair@enabledigital.co and it will get there.');
          box.appendChild(pEl); });
    });
    box.appendChild(f); root.appendChild(box); root.scrollTop = root.scrollHeight;
  }

  function respond(q){
    var root = document.getElementById('agent-root');
    var intro = root.querySelector('.agent-prompts'); if(intro) intro.remove();
    var card = root.querySelector('.agent-card'); if(card) card.remove();
    var msg = root.querySelector('.agent-msg'); if(msg) msg.remove();

    root.appendChild(el('p','agent-you', q));
    var i0 = document.querySelector('.agent-input'); if(i0) i0.value = '';
    var done = thinking(root);
    var hits = search(q);
    // a considered pause: the answer is ready instantly, but arriving instantly reads as a lookup
    setTimeout(function(){ done(); paint(q, hits, root); }, 900 + Math.min(hits.length,3) * 220);
  }

  function paint(q, hits, root){
    if(!hits.length || hits[0].s < 2.5){
      var miss = el('div','agent-answer');
      miss.appendChild(el('p','agent-msg',
        'I cannot find that on this site, and I would rather say so than guess. Blair will know.'));
      var a = el('a','agent-cite','Ask him directly'); a.href='contact.html';
      miss.appendChild(a); root.appendChild(miss);
    } else {
      hits.slice(0,2).forEach(function(hit){
        var box = el('div','agent-answer');
        box.appendChild(el('div','agent-answer-h', hit.e.h));
        box.appendChild(el('p','agent-msg', snippet(hit.e.x, q)));
        var a = el('a','agent-cite', 'Read it on ' + hit.e.t.split('|')[0].split(':')[0].trim());
        a.href = hit.e.p + '.html';
        a.target = '_blank'; a.rel = 'noopener';   // keep the drawer alive behind the page they opened
        a.addEventListener('click', function(){ setTimeout(function(){ followUp(root, q); }, 1200); });
        box.appendChild(a);
        root.appendChild(box);
      });
    }
    root.scrollTop = root.scrollHeight;
  }

  if(window.EnableAgent) window.EnableAgent.on(respond);
  window.EnableAgent.answer = respond;
})();
